import sys

class Fenwick:
    def __init__(self, n):
        self.n = n
        self.bit = [0] * (n + 1)

    def add(self, i, x):
        while i <= self.n:
            self.bit[i] += x
            i += i & -i

    def sum(self, i):
        s = 0
        while i > 0:
            s += self.bit[i]
            i -= i & -i
        return s

def weighted_desc(values):
    m = len(values)
    return sum(c * (m - i) for i, c in enumerate(sorted(values, reverse=True)))

def weighted_asc(values):
    m = len(values)
    return sum(c * (m - i) for i, c in enumerate(sorted(values)))

